import urllib.request, json, sys, time

def get_text(url):
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=60).read().decode()

def get_json(url):
    return json.loads(get_text(url))

ids = [l.strip() for l in open('/app/pdb_ids.txt') if l.strip()]
info = {}
for i in ids:
    try:
        d = get_json(f'https://data.rcsb.org/rest/v1/core/entry/{i}')
        title = d['struct']['title']
        fasta = get_text(f'https://www.rcsb.org/fasta/entry/{i}')
        info[i] = {'title': title, 'fasta': fasta}
        open(f'/app/work/fasta_{i}.fa','w').write(fasta)
        print(f"=== {i} | {title}")
        print(fasta)
        time.sleep(0.5)
    except Exception as e:
        print(f"=== {i} | ERROR {e}")
    sys.stdout.flush()
json.dump(info, open('/app/work/pdb_info.json','w'), indent=1)
print("DONE")
