import json, re
data = json.load(open('fpbase_all.json'))
import glob

def pdb_seqs():
    d = {}
    for f in glob.glob('fasta_*.fa'):
        pid = f.replace('fasta_','').replace('.fa','')
        for line in open(f):
            if line.startswith('>'):
                continue
            s = line.strip()
            if s:
                d[pid] = s
    return d

pdb = pdb_seqs()
# For each PDB seq, find best FPbase match (allowing X to match any 1-3 chars)
for pid, seq in pdb.items():
    # build regex: X -> .{1,3}, others literal
    pat = re.escape(seq).replace(r'\X', '.{1,3}')
    rx = re.compile(pat)
    best = []
    for p in data:
        s = p.get('seq','')
        if not s: continue
        if rx.search(s):
            states = [(st['name'], st.get('ex_max'), st.get('em_max')) for st in p.get('states',[])]
            best.append((p['name'], states))
    print(pid, '->', best if best else 'NO MATCH')
